8623a6b6e","date":"2015-04-20","date_text":null,"kind":"company_exit","asset_class":"private_equity","target":"Websense","portco_name":"Websense","target_website":"forcepoint.com","investor":"Raytheon Company","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["Vista Equity Partners"],"seller":"Vista Equity Partners","round":null,"stake_pct":80.3,"amount":1570000000.0,"currency":"USD","amount_basis":"stake_price","valuation":null,"valuation_currency":null,"headline":"Raytheon and Vista Equity Partners enter agreement to form new cybersecurity company","summary":"Raytheon agreed to combine Raytheon Cyber Products with Vista-owned Websense in a joint venture (later Forcepoint), investing about $1.57 billion in net cash for 80.3% ownership, with Vista also investing.","source_name":"Raytheon via SEC EDGAR (Form 8-K Exhibit 99.1)","source_url":"https://www.sec.gov/Archives/edgar/data/1047122/000104712215000086/exhibit9918-k4202015.htm","evidence":"Joint Venture Formation Raytheon’s net cash contribution is approximately $1.57 billion for an 80.3% ownership of the joint venture.","verified":true},{"key":"pr:d96b165f85dc56265c060ebb5184c565","date":"2014-09-02","date_text":null,"kind":"company_exit","asset_class":"private_equity","target":"MicroEdge","portco_name":"MicroEdge","target_website":null,"investor":"Blackbaud, Inc.","sponsor_is_investor":false,"sponsor_role":"seller","co_investors":[],"seller":"Vista Equity Partners and Bregal Sagemount","round":null,"stake_pct":null,"amount":160000000.0,"currency":"USD","amount_basis":"equity_value","valuation":null,"valuation_currency":null,"headline":"Blackbaud to Acquire MicroEdge","summary":"Blackbaud agreed to acquire grantmaking software provider MicroEdge, a Vista Equity Partners and Bregal Sagemount portfolio company, for an aggregate purchase price of $160 million.","source_name":"Blackbaud via SEC EDGAR (Form 8-K Exhibit 99.1)","source_url":"https://www.sec.gov/Archives/edgar/data/1280058/000128005814000027/ex991september-02x2014.htm","evidence":"MicroEdge is headquartered in New York, and is a portfolio company of Vista Equity Partners and Bregal Sagemount. ... Under the purchase agreement for the transaction, Blackbaud will acquire all of the outstanding equity interests of MicroEdge for an aggregate purchase price of $160 million.","verified":true},{"key":"pr:77fe945fa30b9615dd66eabc9337eb31","date":"2013-09-30","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"ACTIVE Network","portco_name":"ACTIVE Network","target_website":"activenetwork.com","investor":"Vista Equity Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":1050000000.0,"currency":"USD","amount_basis":"enterprise_value","valuation":null,"valuation_currency":null,"headline":"ACTIVE Network to be Acquired by Vista Equity Partners","summary":"Vista agreed to take ACTIVE Network private through a tender offer at $14.50 per share, in a transaction valued at about $1.05 billion.","source_name":"ACTIVE Network via SEC EDGAR (Form 8-K Exhibit 99.1)","source_url":"https://www.sec.gov/Archives/edgar/data/1163932/000119312513385088/d604812dex991.htm","evidence":"ACTIVE Network Stockholders to Receive $14.50 per Share in Cash in Transaction Valued at Approximately $1.05 Billion","verified":true},{"key":"pr:9578a3195e30bf02fcaeeb463bd2a8be","date":"2013-05-20","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"Websense","portco_name":"Websense","target_website":"forcepoint.com","investor":"Vista Equity Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":1000000000.0,"currency":"USD","amount_basis":"enterprise_value","valuation":null,"valuation_currency":null,"headline":"Websense Signs Definitive Agreement to be Acquired by Vista Equity Partners","summary":"Vista agreed to take cybersecurity company Websense private at $24.75 per share in a transaction valued at about $1 billion.","source_name":"Websense via SEC EDGAR (Form 8-K Exhibit 99.1)","source_url":"https://www.sec.gov/Archives/edgar/data/1098277/000119312513227720/d541337dex991.htm","evidence":"Shareholders to receive $24.75 per share in cash in transaction valued at approximately $1 billion","verified":true},{"key":"pr:ac738e294acb64f22dc17eebbcd3cb8a","date":null,"date_text":"November 2010","kind":"company_acquisition","asset_class":"private_equity","target":"Trintech Group","portco_name":"Trintech","target_website":"trintech.com","investor":"Cerasus (Spectrum Equity Investors V)","sponsor_is_investor":false,"sponsor_role":null,"co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":129400000.0,"currency":"USD","amount_basis":"equity_value","valuation":null,"valuation_currency":null,"headline":"Trintech Group plc Form 6-K (November 2010)","summary":"In 2010 Spectrum Equity, through its vehicle Cerasus, agreed to acquire Trintech by scheme of arrangement valuing its entire share capital at about US$129.4 million (before Vista’s later investment).","source_name":"Trintech Group via SEC EDGAR (Form 6-K)","source_url":"https://www.sec.gov/Archives/edgar/data/1094316/000119312510250565/d6k.htm","evidence":"The Acquisition values the entire issued and to be issued share capital of Trintech at approximately US$129.4 million. ... Cerasus was formed at the direction of Spectrum Equity Associates V, L.P., the general partner of Spectrum Equity Investors V, L.P., for the purpose of implementing the Acquisition.","verified":true},{"key":"pr:55c279b06be5d06472b04b4709730df4","date":"2022-03-16","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"FLASH","portco_name":"Flash","target_website":"flashparking.com","investor":"Vista Equity Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["L Catterton"],"seller":null,"round":"growth","stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":1000000000.0,"valuation_currency":"USD","headline":"FLASH Secures Over $250 Million in Round Led by Vista Equity Partners To Advance Connected Mobility Ecosystem","summary":"Cloud parking software company FLASH raised a $250+ million minority strategic investment led by Vista, joined by existing lead investor L Catterton, at a $1B+ valuation.","source_name":"Vista Equity Partners","source_url":"https://www.vistaequitypartners.com/news/flash-secures-over-250-million-in-round-led-by-vista-equity-partners-to-advance-connected-mobility-ecosystem/","evidence":"$1B+ valuation further solidifies FLASH’s leadership position among mobility innovators and accelerates growth ... today announced a $250+ million strategic investment led by Vista Equity Partners (“Vista”), a leading global investment firm focused exclusively on enterprise software, data, and technology-enabled businesses. Vista is joined by existing lead investor L Catterton, other prior investors, and management. The minority investment will be used to expand","verified":null},{"key":"pr:c94fc3ec2c081d6a67e74954dadb7e8a","date":"2017-06-13","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"D+H (DH Corp)","portco_name":"D+H","target_website":null,"investor":"Vista Equity Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Vista Equity Partners closes $4.8 bln acquisition of DH Corp","summary":"PE Hub reported that Vista closed its acquisition of Canadian financial technology company DH Corp (D+H), which Vista later combined with Misys to form Finastra; the headline gives $4.8 bln without stating the currency, so no amount is recorded.","source_name":"PE Hub","source_url":"https://www.pehub.com/vista-equity-partners-closes-4-8-bln-buy-of/","evidence":"Vista Equity Partners closes $4.8 bln acquisition of DH Corp","verified":null},{"key":"pr:421924385a670d577ea1332229886a06","date":"2014-03-28","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"PeopleAdmin","portco_name":"PeopleAdmin","target_website":null,"investor":"Vista Equity Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Vista Equity acquires PeopleAdmin","summary":"PE Hub reported that Vista acquired higher-education talent management software provider PeopleAdmin.","source_name":"PE Hub","source_url":"https://www.pehub.com/vista-equity-acquires-peopleadmin/","evidence":"Vista Equity acquires PeopleAdmin","verified":null},{"key":"pr:f17856946e9b00f374190c3c3d37023d","date":"2018-12-12","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"7Park Data","portco_name":"7Park Data","target_website":null,"investor":"Vista Equity Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Vista Equity Partners Buys Automated Analytics Firm 7Park Data","summary":"Vista purchased 7Park Data, which turns unstructured data into leading performance indicators for investors.","source_name":"CDP Institute","source_url":"https://www.cdpinstitute.org/news/vista-equity-partners-buys-automated-analytics-firm-7park-data/","evidence":"One more deal: Vista Equity Partners has just purchased 7Park Data, which transforms unstructured data into “contextualized Leading Performance indicators” to help investors and managers predict how businesses will perform.","verified":null},{"key":"pr:742ff45b311f43f71a096cfeca8cca51","date":"2017-09-05","date_text":null,"kind":"funding_round","asset_class":"venture_capital","target":"Gather","portco_name":"Gather","target_website":"gatherhere.com","investor":"Vista Equity Partners","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Gather Partners with Vista Equity Partners to Meet Growing Demand for Event Management Technology for Restaurants and Venues","summary":"Restaurant and venue event management software provider Gather announced a strategic investment from and partnership with Vista.","source_name":"PRWeb","source_url":"https://www.prweb.com/releases/gather_partners_with_vista_equity_partners_to_meet_growing_demand_for_event_management_technology_for_restaurants_and_venues/prweb14659812.htm","evidence":"Gather , the leading event management software for restaurants and venues, today announced a strategic investment from and partnership with Vista Equity Partners , a leading investment firm for enterprise software, data, and technology-enabled businesses.","verified":null}]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'Vista Equity Partners'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'Vista Equity Partners'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'vistaequitypartners.com WordPress REST /wp-json/wp/v2/company (150 companies, 2 pages) + each /company/<slug>/ page for year, status, HQ, strategy, industry, website; supplemented with Vista''s own newsroom (/wp-json/wp/v2/media_library press releases incl. Vista Credit Partners), Vista Year-in-Review microsites 2016-2025, FTC HSR early-termination notices, SEC EDGAR filings and company press relea', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'Vista Equity Partners', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
